"""Strict JSON parsing and deterministic replay, shared by SDK and central server."""

import json
from dataclasses import dataclass, field
from time import perf_counter

from .core import SCHEMA_VERSION, Challenge, HexCoordinate, iso_date
from .simulation import IllegalMove, Simulation

DEFAULT_MAX_BYTES = 2 * 1024 * 1024
DEFAULT_MAX_ACTIONS = 10_000


def _pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"Duplicate JSON key: {key}")
        result[key] = value
    return result


def _constant(value):
    raise ValueError("Nonfinite numbers are not JSON")


def strict_loads(raw: str | bytes):
    return json.loads(raw, object_pairs_hook=_pairs, parse_constant=_constant)


@dataclass
class ValidationReport:
    legal: bool = False
    solved: bool = False
    action_count: int = 0
    covered_cells: int = 0
    error: dict | None = None
    events: list[dict] = field(default_factory=list)
    validation_ms: float = 0

    def to_dict(self) -> dict:
        return dict(
            legal=self.legal,
            solved=self.solved,
            action_count=self.action_count,
            covered_cells=self.covered_cells,
            error=self.error,
            events=self.events,
            validation_ms=self.validation_ms,
        )


def _fields(value: object, expected: set[str]) -> dict:
    if not isinstance(value, dict) or set(value) != expected:
        raise ValueError("Expected exactly these fields: " + ", ".join(sorted(expected)))
    return value


def validate_trace(
    raw: bytes | str,
    challenge: Challenge,
    *,
    max_bytes=DEFAULT_MAX_BYTES,
    max_actions=DEFAULT_MAX_ACTIONS,
) -> ValidationReport:
    start = perf_counter()
    report = ValidationReport()
    index = None
    attempted_action = None
    code = "invalid_json"
    simulation = Simulation(challenge)
    try:
        if len(raw.encode("utf-8") if isinstance(raw, str) else raw) > max_bytes:
            code = "upload_too_large"
            raise ValueError("Trace exceeds the configured byte limit")
        trace = strict_loads(raw)
        code = "invalid_schema"
        trace = _fields(
            trace, {"schema_version", "puzzle_version", "challenge_id", "date", "actions"}
        )
        if type(trace["schema_version"]) is not int or trace["schema_version"] != SCHEMA_VERSION:
            raise ValueError("Unsupported schema_version")
        code = "challenge_mismatch"
        if (
            trace["puzzle_version"] != challenge.puzzle_version
            or trace["challenge_id"] != challenge.id
        ):
            raise ValueError(
                "Trace challenge ID or puzzle version does not match the assigned challenge"
            )
        if iso_date(trace["date"]) != challenge.date:
            raise ValueError("Trace date does not match the assigned challenge")
        code = "invalid_schema"
        actions = trace["actions"]
        if not isinstance(actions, list):
            raise ValueError("actions must be an array")
        report.action_count = len(actions)
        if len(actions) > max_actions:
            code = "too_many_actions"
            raise ValueError("Trace exceeds the configured action limit")
        for action in actions:
            index = len(report.events)
            attempted_action = action
            code = "invalid_action"
            if not isinstance(action, dict) or action.get("action") not in ("place", "remove"):
                raise ValueError("Action must be place or remove")
            if action["action"] == "place":
                _fields(action, {"action", "piece_id", "origin", "rotation", "flipped"})
                origin = _fields(action["origin"], {"q", "r"})
                if any(type(origin[k]) is not int or abs(origin[k]) > 1_000_000 for k in origin):
                    raise ValueError("Origin coordinates must be integers within ±1000000")
                placement = simulation.place(
                    action["piece_id"],
                    HexCoordinate(**origin),
                    action["rotation"],
                    action["flipped"],
                )
            else:
                _fields(action, {"action", "piece_id"})
                placement = simulation.remove(action["piece_id"])
            report.events.append({"action": action["action"], "placement": placement.to_dict()})
        report.legal = True
        report.solved = simulation.is_solved
    except (ValueError, TypeError, RecursionError, UnicodeError) as error:
        try:
            preview = json.dumps(attempted_action)[:1000] if index is not None else None
        except (ValueError, RecursionError):
            preview = "Action is too deeply nested to preview"
        report.error = {
            "index": index,
            "code": error.code if isinstance(error, IllegalMove) else code,
            "message": str(error)[:500],
            "action_preview": preview,
            "cells": [c.to_dict() for c in error.cells] if isinstance(error, IllegalMove) else [],
        }
    report.covered_cells = len(simulation.occupied)
    report.validation_ms = (perf_counter() - start) * 1000
    return report
